import csv
import io


def check(fields):
    if len(fields) != 4:
        return f"expected 4 fields, got {len(fields)}"
    loan_id, borrower, city, amount = fields
    if not loan_id.strip().lstrip("-").isdigit():
        return "loan_id is not an integer"
    if not borrower.strip():
        return "borrower is required"
    try:
        float(amount)
    except ValueError:
        return "amount is not a number"
    return None


def bad_rows(text):
    bad = []
    reader = csv.reader(io.StringIO(text))
    next(reader, None)
    for fields in reader:
        reason = check(fields)
        if reason:
            bad.append([reader.line_num, reason])
    return bad

