import json
import math

lines = [
    '{"id": 1, "amount": "19.99", "currency": "EUR"}',
    '{"id": 2, "amount": "nan", "currency": "EUR"}',
    '{"id": 3, "currency": "USD"}',
    '{"id": 4, "amount": "5.00", "curr',
    '',
    '{"id": "6", "amount": "7.50", "currency": "USD"}',
]


def problem(record):
    if not isinstance(record.get("id"), int):
        return "id is not an integer"
    if "amount" not in record:
        return "amount is missing"
    try:
        amount = float(record["amount"])
    except (TypeError, ValueError):
        return "amount is not a number"
    if not math.isfinite(amount):
        return "amount is not finite"
    return None


accepted, quarantine, blank = [], [], 0
for number, line in enumerate(lines, start=1):
    if not line.strip():
        blank += 1
        continue
    try:
        record = json.loads(line)
    except json.JSONDecodeError:
        quarantine.append((number, "not valid JSON"))
        continue
    reason = problem(record)
    if reason:
        quarantine.append((number, reason))
    else:
        accepted.append(record["id"])

print("accepted ids:", accepted)
for number, reason in quarantine:
    print(f"quarantined line {number}: {reason}")
print(f"read {len(lines)}, blank {blank}, accepted {len(accepted)}, rejected {len(quarantine)}")

