import json

REQUIRED = {"order_id": int, "amount": int}
OPTIONAL = {"coupon": str}


def read(line):
    record = json.loads(line)
    missing = [name for name in REQUIRED if name not in record]
    if missing:
        return "quarantine", "missing " + ", ".join(missing)
    wrong = [name for name, kind in REQUIRED.items() if not isinstance(record[name], kind)]
    if wrong:
        return "quarantine", "wrong type for " + ", ".join(wrong)
    known = {**REQUIRED, **OPTIONAL}
    row = {name: record.get(name) for name in known}
    row["_extra"] = {key: value for key, value in record.items() if key not in known}
    return "load", row


